PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,login TEXT UNIQUE,secret TEXT,role TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(digest TEXT PRIMARY KEY,user_id INTEGER REFERENCES users,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS stations(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,address TEXT NOT NULL,cap INTEGER NOT NULL CHECK(cap>0));
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,contact TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bikes(id INTEGER PRIMARY KEY,serial TEXT UNIQUE NOT NULL,type TEXT NOT NULL,color TEXT NOT NULL,supplier INTEGER REFERENCES suppliers,station INTEGER REFERENCES stations,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cards(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,owner INTEGER REFERENCES users,dest INTEGER REFERENCES stations,hours INTEGER NOT NULL,fee INTEGER NOT NULL,deposit INTEGER NOT NULL,status TEXT NOT NULL,issued TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rentals(id INTEGER PRIMARY KEY,owner INTEGER REFERENCES users,bike INTEGER REFERENCES bikes,card INTEGER REFERENCES cards,origin INTEGER REFERENCES stations,dest INTEGER REFERENCES stations,started TEXT DEFAULT CURRENT_TIMESTAMP,ended TEXT,damaged INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS active_owner ON rentals(owner) WHERE ended IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS active_bike ON rentals(bike) WHERE ended IS NULL;
CREATE TABLE IF NOT EXISTS checks(id INTEGER PRIMARY KEY,bike INTEGER REFERENCES bikes,tech INTEGER REFERENCES users,diagnosis TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS claims(id INTEGER PRIMARY KEY,bike INTEGER REFERENCES bikes,inspection INTEGER REFERENCES checks,rental INTEGER REFERENCES rentals,diagnosis TEXT NOT NULL,status TEXT NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trucks(id INTEGER PRIMARY KEY,name TEXT NOT NULL,capacity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS missions(id INTEGER PRIMARY KEY,tech INTEGER REFERENCES users,truck INTEGER REFERENCES trucks,origin INTEGER REFERENCES stations,dest INTEGER REFERENCES stations,qty INTEGER NOT NULL,instructions TEXT NOT NULL,step INTEGER NOT NULL DEFAULT 0,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cargo(mission INTEGER REFERENCES missions,bike INTEGER REFERENCES bikes,kind TEXT,PRIMARY KEY(mission,bike));
CREATE TABLE IF NOT EXISTS repair_plans(claim INTEGER PRIMARY KEY REFERENCES claims,scheduled TEXT NOT NULL,work TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS retirements(bike INTEGER PRIMARY KEY REFERENCES bikes,reason TEXT NOT NULL,manager INTEGER REFERENCES users,created TEXT DEFAULT CURRENT_TIMESTAMP);
